public class Main {
    interface Spell { String cast(); }
    static class Fireball implements Spell { public String cast() { return "BOOM"; } }
    static class Heal implements Spell { public String cast() { return "HEAL"; } }
    static class Mage {
        private Spell spell;
        Mage(Spell spell) { this.spell = spell; }
        void action() { System.out.println(spell.cast()); }
    }
    public static void main(String[] args) {
        Mage m = new Mage(new Fireball());
        m.action();
        m.spell = new Heal(); // swap strategy
        m.action();
    }
}

class SpellEventBus {
    private final List<SpellObserver> observers = new ArrayList<>();
    void register(SpellObserver o) { observers.add(o); }
    void cast(String spell) { observers.forEach(o -> o.onCast(spell)); }
    // No unregister method!
}

// In a UI component created and destroyed repeatedly:
SpellEventBus bus = new SpellEventBus();
for (int i = 0; i < 100; i++) {
    bus.register(spell -> System.out.println(spell)); // lambda registered, never removed
}

