public class Main {
    interface Boost { int apply(int base); }
    public static void main(String[] args) {
        Boost b1 = base -> base + 10;
        Boost b2 = base -> base * 3;
        Boost combined = base -> b2.apply(b1.apply(base));
        System.out.println(combined.apply(5));
    }
}

interface Spell { int power(); }
class BasicSpell implements Spell { public int power() { return 40; } }
class EmpoweredSpell implements Spell {
    private final Spell wrapped;
    EmpoweredSpell(Spell wrapped) { this.wrapped = wrapped; }
    public int power() { return 40 + 30; } // hardcoded!
}
Spell s = new EmpoweredSpell(new EmpoweredSpell(new BasicSpell()));
System.out.println(s.power()); // prints 70, expected 100

public class Main {
    interface Command { void execute(); void undo(); }
    static class CastSpellCommand implements Command {
        private final String spellName;
        CastSpellCommand(String spellName) { this.spellName = spellName; }
        public void execute() { System.out.println("Casting: " + spellName); }
        public void undo()    { System.out.println("Undoing: " + spellName); }
    }
    public static void main(String[] args) {
        Command cmd = new CastSpellCommand("Fireball");
        cmd.execute();
        cmd.undo();
    }
}
